 // hist is zeroed by the caller. n is any size from 0 to 20'000'000; the sums
 // never overflow int64.
 extern "C" void scan_and_histogram(const int64_t* in, int64_t* out, size_t n, uint64_t* hist) {
+    // Initialize hist to zero
     for (int b = 0; b < 256; ++b) hist[b] = 0;
+
+    // 4 private sub-histograms (uint32_t is enough per chunk)
+    uint32_t hist0[256] = {0};
+    uint32_t hist1[256] = {0};
+    uint32_t hist2[256] = {0};
+    uint32_t hist3[256] = {0};
+
     int64_t sum = 0;
-    for (size_t i = 0; i < n; ++i) {
+    size_t i = 0;
+
+    // Process 4 elements per iteration to break dependency chains
+    for (; i + 3 < n; i += 4) {
+        int64_t v0 = in[i];
+        int64_t v1 = in[i + 1];
+        int64_t v2 = in[i + 2];
+        int64_t v3 = in[i + 3];
+
+        sum += v0;
+        out[i] = sum;
+        hist0[v0 & 255]++;
+
+        sum += v1;
+        out[i + 1] = sum;
+        hist1[v1 & 255]++;
+
+        sum += v2;
+        out[i + 2] = sum;
+        hist2[v2 & 255]++;
+
+        sum += v3;
+        out[i + 3] = sum;
+        hist3[v3 & 255]++;
+    }
+
+    // Remainder loop
+    for (; i < n; ++i) {
         sum += in[i];
         out[i] = sum;
-        hist[in[i] & 255]++;
+        hist0[in[i] & 255]++;
+    }
+
+    // Merge sub-histograms into final hist
+    for (int b = 0; b < 256; ++b) {
+        hist[b] = (uint64_t)hist0[b] + hist1[b] + hist2[b] + hist3[b];
     }
 }
